{"code": "from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel, conlist
from typing import List, Dict, Any

app = FastAPI()

_KNOWN = {"a", "b", "c"}

class BulkVerifyRequest(BaseModel):
    __root__: conlist(str)

class ResultItem(BaseModel):
    index: int
    status: str
    reason: str = None

class BulkVerifyResponse(BaseModel):
    results: List[ResultItem]
    failed: int

@app.post("/bulk/verify", response_model=BulkVerifyResponse, status_code=200)
async def bulk_verify(payload: BulkVerifyRequest):
    results = []
    for index, key in enumerate(payload.__root__):
        if not isinstance(key, str):
            results.append(ResultItem(index=index, status="invalid", reason="not a string"))
        elif key in _KNOWN:
            results.append(ResultItem(index=index, status="ok"))
        else:
            results.append(ResultItem(index=index, status="unknown"))

    failed = sum(1 for r in results if r.status != "ok")
    status = 200 if failed == 0 else 207
    return JSONResponse(content={"results": results, "failed": failed}, status_code=status)

@app.get("/bulk/limits")
async def limits():
    return JSONResponse(content={"max_items": 100, "known": sorted(_KNOWN)})"}

{"code": "from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import JSONResponse
from pydantic import BaseModel, constr

app = FastAPI()

_DOCS = {"d1": {"id": "d1", "title": "spec", "version": 3}}

class Document(BaseModel):
    id: str
    title: constr(min_length=1)
    version: int

@app.get("/docs/{doc_id}")
async def get_doc(doc_id: str):
    doc = _DOCS.get(doc_id)
    if doc is None:
        raise HTTPException(status_code=404, detail={"error": "doc not found"})
    response = JSONResponse(content=doc)
    response.headers["ETag"] = f'W/"{doc["version"]}"'
    return response

@app.patch("/docs/{doc_id}")
async def patch_doc(doc_id: str, title: str, if_match: str = Header(None)):
    doc = _DOCS.get(doc_id)
    if doc is None:
        raise HTTPException(status_code=404, detail={"error": "doc not found"})

    if if_match is None:
        raise HTTPException(status_code=428, detail={"error": "If-Match header is required", "code": "PRECONDITION_REQUIRED"})
    if if_match != f'W/"{doc["version"]}"':
        raise HTTPException(status_code=409, detail={"error": "version conflict", "expected": doc["version"]})

    response = JSONResponse(content={**doc, "title": title, "version": doc["version"] + 1})
    response.headers["ETag"] = f'W/"{doc["version"] + 1}"'
    return response
"}

